"use client";

import { useMemo, useRef, useState, type ReactNode } from "react";
import { DataGridProvider, DataGridRoot, DataGridHeader, DataGridBody, defineColumns, type FilterNode } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridLazyRows } from "@/registry/default/components/data-grid-lazy/data-grid-lazy";
import { DataGridHeaderFilter } from "@/registry/default/components/data-grid-toolbar/data-grid-toolbar";
import type { DemoRow } from "./demo-data";
import { createRemoteServer, type RemoteFilterNode } from "./fake-remote-server";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 120, flex: 1 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 110, flex: 1 },
  { id: "age", header: "Age", accessorKey: "age", type: "number", width: 90, flex: 1 },
] as const);

/**
 * A lazy grid filtered by a fake server. `filterMode="server"` keeps the view as an identity map, the
 * header filter lists the server's values through `fetchFilterValues`, and a filter change asks the
 * server for the new total before it resets the loaded rows.
 */
export default function DataGridServerFilterDemo(): ReactNode {
  const server = useMemo(() => createRemoteServer(), []);
  const [applied, setApplied] = useState<{ filters: readonly RemoteFilterNode[]; total: number }>({ filters: [], total: server.total });
  const latestChange = useRef(0);

  const lazy = useDataGridLazyRows<DemoRow>({
    total: applied.total,
    getRowId: (row) => row.id,
    spec: { sorts: [], filters: applied.filters as FilterNode[], search: "" },
    fetchRows: ({ start, end, signal, spec }) => server.fetchRange({ start, end, filters: spec.filters as RemoteFilterNode[], signal }).then((page) => page.rows),
  });

  const onFilterChange = async (next: FilterNode[]) => {
    const change = ++latestChange.current;
    const { total } = await server.fetchRange({ start: 0, end: 0, filters: next as RemoteFilterNode[] });
    if (change !== latestChange.current) return;
    setApplied({ filters: next as RemoteFilterNode[], total });
    lazy.reset();
  };

  return (
    <div className="w-full flex flex-col gap-2">
      <p className="text-sm text-muted-foreground">
        {applied.total.toLocaleString("en-US")} rows match<span className={lazy.isLoading ? undefined : "invisible"}> · fetching…</span>
      </p>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider
          data={lazy.gridProps.data}
          columns={columns}
          getRowId={lazy.gridProps.getRowId}
          onDataChange={lazy.onDataChange}
          onRenderedRowsChange={lazy.gridProps.onRenderedRowsChange}
          filterMode="server"
          onFilterChange={onFilterChange}
          fetchFilterValues={({ columnId, search, filters, signal }) => server.fetchValues({ columnId, search, filters: filters as RemoteFilterNode[], signal })}
          readOnly
        >
          <DataGridRoot className="min-h-0 flex-1 rounded-none border-none" renderHeaderFilter={(ctx) => <DataGridHeaderFilter {...ctx} />}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

import { applyChange, type DataChange } from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

export type RemoteSort = { columnId: string; direction: "asc" | "desc" };
export type RemoteFilter = { columnId: string; operator: string; value?: string | [string, string] | string[] };
export type RemoteFilterGroup = { join: "and" | "or"; filters: readonly RemoteFilterNode[] };
export type RemoteFilterNode = RemoteFilter | RemoteFilterGroup;
export type RemoteQuery = {
  page: number;
  pageSize: number;
  search?: string;
  sorts?: readonly RemoteSort[];
  filters?: readonly RemoteFilterNode[];
  signal?: AbortSignal;
};

const LATENCY_MS = 300;
const MAX_FILTER_DEPTH = 2;
const MAX_FILTER_LEAVES = 64;
const MAX_FILTER_GROUPS = 16;
const FILTERABLE_COLUMNS: ReadonlySet<string> = new Set(["id", "name", "email", "age", "active", "role", "joined", "score"]);

const isGroup = (node: RemoteFilterNode): node is RemoteFilterGroup => "filters" in node;

/** Checks an untrusted filter tree before it is evaluated: depth, group count, leaf count, and join values. A real server also caps the request body size. */
function assertFilterTree(nodes: readonly RemoteFilterNode[], allowed: ReadonlySet<string>): void {
  let leaves = 0;
  let groups = 0;
  const walk = (list: readonly RemoteFilterNode[], depth: number) => {
    if (!Array.isArray(list)) throw new Error("invalid filter tree");
    for (const node of list as readonly RemoteFilterNode[]) {
      if (isGroup(node)) {
        if (depth >= MAX_FILTER_DEPTH || ++groups > MAX_FILTER_GROUPS || (node.join !== "and" && node.join !== "or")) throw new Error("invalid filter group");
        walk(node.filters, depth + 1);
      } else {
        if (!allowed.has(node.columnId) || ++leaves > MAX_FILTER_LEAVES) throw new Error("invalid filter");
      }
    }
  };
  walk(nodes, 0);
}

function delay(signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, LATENCY_MS);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("aborted", "AbortError"));
    });
  });
}

/**
 * Fake "database" of 1,000 rows behind a 300 ms round trip for the server-side examples:
 * `fetchPage` applies search/filter/sort on the "server" and returns one page plus the total;
 * `applyOps` writes the grid's committed operations back into the store (a stand-in for your API route),
 * so edits survive a refetch.
 */
export function createRemoteServer() {
  const rows = new Map<string, DemoRow>(generateDemoRows(1000).map((row) => [row.id, row]));
  let order = [...rows.keys()];

  const cell = (row: DemoRow, columnId: string): string => {
    const value = row[columnId as keyof DemoRow];
    return value == null ? "" : String(value);
  };

  const matchFilter = (row: DemoRow, filter: RemoteFilter): boolean => {
    const text = cell(row, filter.columnId);
    const num = Number(text);
    const v = filter.value;
    switch (filter.operator) {
      case "contains":
        return text.toLowerCase().includes(String(v).toLowerCase());
      case "notContains":
        return !text.toLowerCase().includes(String(v).toLowerCase());
      case "equals":
        return text === String(v);
      case "notEquals":
        return text !== String(v);
      case "startsWith":
        return text.startsWith(String(v));
      case "endsWith":
        return text.endsWith(String(v));
      case "empty":
        return text === "";
      case "notEmpty":
        return text !== "";
      case "gt":
        return !Number.isNaN(num) && num > Number(v);
      case "gte":
        return !Number.isNaN(num) && num >= Number(v);
      case "lt":
        return !Number.isNaN(num) && num < Number(v);
      case "lte":
        return !Number.isNaN(num) && num <= Number(v);
      case "isBetween": {
        const [min, max] = v as [string, string];
        if (!Number.isNaN(num)) return (min === "" || num >= Number(min)) && (max === "" || num <= Number(max));
        return (min === "" || text >= min) && (max === "" || text <= max);
      }
      case "isAnyOf":
        return (v as string[]).some((entry) => entry.toLowerCase() === text.toLowerCase());
      case "isNoneOf":
        return !(v as string[]).some((entry) => entry.toLowerCase() === text.toLowerCase());
      default:
        return true;
    }
  };

  async function select(query: Pick<RemoteQuery, "search" | "sorts" | "filters" | "signal">): Promise<DemoRow[]> {
    await delay(query.signal);
    let list = order.map((id) => rows.get(id)!);
    if (query.search) {
      const needle = query.search.toLowerCase();
      list = list.filter((row) => Object.values(row).some((value) => String(value).toLowerCase().includes(needle)));
    }
    const filters = query.filters ?? [];
    if (filters.length > 0) {
      assertFilterTree(filters, FILTERABLE_COLUMNS);
      const matchNode = (row: DemoRow, node: RemoteFilterNode): boolean => {
        if (!isGroup(node)) return matchFilter(row, node);
        if (node.filters.length === 0) return true;
        return node.join === "or" ? node.filters.some((f) => matchNode(row, f)) : node.filters.every((f) => matchNode(row, f));
      };
      list = list.filter((row) => filters.every((f) => matchNode(row, f)));
    }
    const sorts = query.sorts ?? [];
    if (sorts.length > 0) {
      list = [...list].sort((a, b) => {
        for (const s of sorts) {
          const av = a[s.columnId as keyof DemoRow];
          const bv = b[s.columnId as keyof DemoRow];
          const delta = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv));
          if (delta !== 0) return s.direction === "asc" ? delta : -delta;
        }
        return 0;
      });
    }
    return list;
  }

  async function fetchPage(query: RemoteQuery): Promise<{ rows: DemoRow[]; total: number }> {
    const list = await select(query);
    const start = (query.page - 1) * query.pageSize;
    return { rows: list.slice(start, start + query.pageSize), total: list.length };
  }

  /** The rows `[start, end)` of the filtered, sorted list plus its total, for a lazy grid. */
  async function fetchRange(query: Omit<RemoteQuery, "page" | "pageSize"> & { start: number; end: number }): Promise<{ rows: DemoRow[]; total: number }> {
    const list = await select(query);
    return { rows: list.slice(query.start, query.end), total: list.length };
  }

  /** The distinct values of a column with their row counts, filtered by a case-insensitive `search` and capped at `limit`. */
  async function fetchValues(query: { columnId: string; search: string; filters?: readonly RemoteFilterNode[]; limit?: number; signal?: AbortSignal }): Promise<{ values: { label: string; count: number }[] }> {
    if (!FILTERABLE_COLUMNS.has(query.columnId)) throw new Error("invalid column");
    const list = await select({ filters: query.filters, signal: query.signal });
    const counts = new Map<string, number>();
    const needle = query.search.toLowerCase();
    for (const row of list) {
      const label = cell(row, query.columnId);
      if (needle === "" || label.toLowerCase().includes(needle)) counts.set(label, (counts.get(label) ?? 0) + 1);
    }
    const values = [...counts].map(([label, count]) => ({ label, count })).sort((a, b) => a.label.localeCompare(b.label));
    return { values: values.slice(0, query.limit ?? 200) };
  }

  function applyOps(ops: DataChange<DemoRow>["ops"]): void {
    const next = applyChange(order.map((id) => rows.get(id)!), { ops, source: "app" }, (row) => row.id);
    rows.clear();
    for (const row of next) rows.set(row.id, row);
    order = next.map((row) => row.id);
  }

  return { total: rows.size, fetchPage, fetchRange, fetchValues, applyOps };
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
